def sum_Pairs(arr, n):
    """Write a python function to find the sum of absolute differences in all pairs of the given array."""
    if arr is None:
        return 0
    values = list(arr)
    if n is not None:
        if n <= 0:
            return 0
        values = values[:n]
    if len(values) < 2:
        return 0
    values.sort()
    total = 0
    prefix = 0
    for i, value in enumerate(values):
        total += value * i - prefix
        prefix += value
    return total
